function calculation(a,target=state.goal.target,g=state.goal){if(!Number.isFinite(target)||target<0||!Number.isFinite(g.reserve)||g.reserve<0)return{valid:false,reason:'Écris un objectif et un argent de côté corrects.'};if(!Number.isInteger(g.players)||g.players<1||g.players>100)return{valid:false,reason:'Écris un nombre de joueurs entre 1 et 100, sans virgule.'};if(!a)return{valid:false,reason:'Choisis une activité dans la liste.'};if(a.players>g.players)return{valid:false,reason:'Cette activité se joue à '+a.players+' joueurs.'};return E.goal({...g,target:target+g.reserve,reserve:g.reserve,activity:a});}
function selectedGoal(config=state){return B.goal(config,sourceActivities);}
function chart(points,label){if(window.LKCalcVisuals)return window.LKCalcVisuals.create(helpers).plot('c-goal-curve',label,points.map(p=>({label:p[0],value:p[1]})),'$');if(points.length<2)return '';const vals=points.map(p=>p[1]),lo=Math.min(0,...vals),hi=Math.max(...vals,1),span=hi-lo||1,px=i=>60+i/(points.length-1)*400,py=v=>128-(v-lo)/span*100;const path=points.map((p,i)=>(i?'L':'M')+px(i).toFixed(1)+' '+py(p[1]).toFixed(1)).join(' ');return '<figure class="calc-chart"><svg viewBox="0 0 500 162" role="img" aria-label="'+esc(label)+'"><title>'+esc(label)+'</title>'+[0,.5,1].map(t=>'<line class="gridline" x1="60" y1="'+(128-t*100)+'" x2="460" y2="'+(128-t*100)+'"/>').join('')+'<text x="4" y="28">$</text><text x="4" y="130">'+nf.format(lo)+'</text><path class="area" d="'+path+' L460 128 L60 128 Z"/><path class="path" d="'+path+'"/><text x="60" y="155">'+esc(points[0][0])+'</text><text x="460" y="155" text-anchor="end">'+esc(points.at(-1)[0])+'</text></svg><figcaption>'+esc(label)+'</figcaption></figure>';}
function renderGoal(){
 const r=selectedGoal(),g=state.goal,continuous=state.model==='continuous';let html='<p class="calc-kicker">MA RÉPONSE</p><span class="calc-tag">CALCULÉ AVEC TES CHIFFRES</span>';
 if(!r.valid){html+=warning(r.reason)+'<p class="calc-note">Corrige la case signalée pour voir ta réponse.</p>';}else{
  const reached=r.missing===0,total=r.totalMinutes??0,days=r.days??r.sessions;
  html+='<p class="calc-answer b-answer" data-short="'+esc(reached?'C’est bon !':hours(total/60)+' de jeu · '+nf.format(days)+' jour'+(days>1?'s':''))+'">'+(reached?'Bravo, tu as déjà assez d’argent pour ton objectif.':'Il te manque <b>'+money(r.missing)+'</b>'+(continuous?'':' (achat de départ compris)')+'. En jouant <b>'+hours(g.dailyMinutes/60)+'</b> par jour, tu y arrives en <b><span data-c-number="goal-sessions">'+nf.format(days)+'</span> jour'+(days>1?'s':'')+'</b>.')+'</p>';
  html+='<div class="calc-result-main">'+(reached?'C’est bon !':hours(total/60))+'</div><p class="calc-result-sub">'+(reached?'Tu peux choisir un objectif plus grand.':'de jeu en tout')+'</p>';
  html+=stats([['Il te manque',money(r.missing)],['Tu auras à la fin',money(r.finalCapital)],['Tu gardes de côté',money(g.reserve)]]);
  const active=r.activeMinutes??(continuous?total:null),wait=r.waitMinutes??(active===null?null:total-active);
  if(!continuous)html+=stats([['Nombre de missions',nf.format(r.runs)],['Temps de jeu',hours(active===null?null:active/60)],['Temps d’attente',hours(wait===null?null:wait/60)]]);
  const start=g.capital-(r.investment||0);
  if(continuous&&!reached){const points=Array.from({length:5},(_,i)=>[hours(total*i/4/60),start+(r.finalCapital-start)*i/4]);html+=chart(points,'Ton argent : '+money(start)+' au départ, '+money(r.finalCapital)+' après '+hours(total/60)+' de jeu, si tu gagnes toujours pareil.');}
  if(!continuous&&!reached)html+='<p class="calc-note">Tu es payé à la fin de chaque mission. Une mission pas finie ne rapporte rien.</p>';
  html+='<div class="calc-next-action"><strong>'+ (reached?'Et maintenant ?':'Ta prochaine étape')+'</strong><p>'+esc(reached?'Choisis un nouvel objectif ou prépare ton prochain achat.':continuous?'Joue '+hours(Math.min(g.dailyMinutes,total)/60)+', puis reviens écrire combien tu as maintenant dans la case « J’ai déjà ».':'Commence par '+(g.selected==='mixed'?'la première activité de ta rotation':findActivity(g.selected)?.name||'ton activité')+'. Il te faut l’argent des frais avant de commencer.')+'</p></div>';
  html+='<label class="calc-progress-label" for="goal-progress">Tu as déjà '+nf.format(g.target>0?Math.max(0,Math.min(100,(g.capital-g.reserve)/g.target*100)):100)+' % de ton objectif</label><progress id="goal-progress" class="calc-progress" max="100" value="'+(g.target>0?Math.max(0,Math.min(100,(g.capital-g.reserve)/g.target*100)):100)+'"></progress>';
  html+='<details><summary>Comment est-ce calculé ?</summary><p class="calc-note">'+(continuous?'Ce qu’il te manque = ce que tu veux − ce que tu as (sans compter l’argent mis de côté). Temps de jeu = ce qu’il te manque ÷ ce que tu gagnes par heure. Nombre de jours = temps de jeu ÷ ton temps de jeu par jour, arrondi au-dessus.':'Objectif total = ce que tu veux + l’argent mis de côté. Ce qu’il faut acheter avant de commencer est payé au départ. Chaque mission rapporte sa récompense × ta part − tes frais, et les frais se paient avant. Si tu alternes, les activités se suivent dans l’ordre A, B, C. Une mission se fait en entier ou pas du tout, et les attentes sont comptées.')+' On compte une partie par jour : tu finis le jour '+days+' si tu joues tous les jours. Rien n’est relié à ton compte GTA.</p></details>';
  if(!firstResult){emit('first_valid_result');firstResult=true;}
 }
 $('goal-results').innerHTML=html;
 const scenarios=state.activities.map(a=>({...a,investment:a.owned?0:a.investment})).map(a=>({a,r:calculation(a)}));
 const valid=scenarios.filter(x=>x.r.valid&&x.r.missing>0),fastest=valid.slice().sort((a,b)=>a.r.totalMinutes-b.r.totalMinutes)[0]?.a.id,cheapest=valid.slice().sort((a,b)=>a.a.investment-b.a.investment)[0]?.a.id;
 $('goal-routes').innerHTML=scenarios.map(({a,r})=>'<article class="calc-route '+(state.model==='cycles'&&g.selected===a.id?'is-selected':'')+'"><h4>'+esc(a.name)+'</h4><span class="calc-tag">'+(a.id===fastest?'Le plus rapide des 3':a.id===cheapest?'Le moins cher pour commencer':'Entre les deux')+'</span><strong>'+(r.valid?hours(r.totalMinutes/60):'Pas possible')+'</strong><p>'+esc(r.valid?r.sessions+' jour(s) de jeu · '+r.runs+' mission(s)':r.reason)+'</p><dl><dt>À acheter avant de commencer</dt><dd>'+money(a.investment)+'</dd><dt>Durée d’une mission, préparation comprise</dt><dd>'+hours((a.duration+a.prep)/60)+'</dd></dl><button class="calc-text-button" data-scenario="'+a.id+'">Choisir cette activité ↗</button></article>').join('');
 $('goal-sensitivity').innerHTML=continuous&&r.valid?'<h3>Et si je gagne plus, ou moins ?</h3><div class="calc-routes">'+[.8,1,1.2].map(m=>{const v=E.goalContinuous({...g,hourly:g.hourly*m});return'<article class="calc-route"><span class="calc-tag">'+(m===1?'TON CHIFFRE':m<1?'20 % DE MOINS':'20 % DE PLUS')+'</span><strong>'+hours(v.valid?v.totalMinutes/60:null)+'</strong><p>'+money(g.hourly*m)+' par heure</p></article>';}).join('')+'</div><p class="calc-note">On refait le calcul avec 20 % de moins et 20 % de plus. Ce n’est pas une prévision.</p>':'';
 renderReference();
}
function renderReference(){$('reference-results').innerHTML='';}
function renderActivities(){let rows=activityList().map(a=>({a,r:E.activity(a)}));const mode=$('activity-filter')?.value||'hourly';if(mode==='solo')rows=rows.filter(x=>x.a.players===1);if(mode==='short')rows=rows.filter(x=>x.r.valid&&x.r.activeMinutes<=30);if(mode==='accessible')rows=rows.filter(x=>x.a.investment+x.a.cost<=state.goal.capital-state.goal.reserve&&x.a.players<=state.goal.players);rows.sort((a,b)=>(mode==='investment'?a.a.investment-b.a.investment:(b.r.hourly??-1e20)-(a.r.hourly??-1e20))||a.a.name.localeCompare(b.a.name,'fr'));
 $('activity-results').innerHTML=rows.length?'<div class="calc-table-wrap" tabindex="0"><table class="calc-table"><caption>Ce que rapportent tes activités</caption><thead><tr><th>Activité</th><th>Gain par mission</th><th>Gain par heure, attente comprise</th><th>Temps de jeu</th><th>Achat de départ remboursé après</th><th>Statut</th></tr></thead><tbody>'+rows.map(({a,r})=>'<tr><th>'+esc(a.name)+'</th><td>'+money(r.net)+'</td><td>'+money(r.hourly)+'</td><td>'+hours(r.valid?r.activeMinutes/60:null)+'</td><td>'+(r.paybackRuns!==null?r.paybackRuns+' mission(s)':'Jamais')+'</td><td>'+esc(r.valid?statusLabels[a.status]||'Non confirmé':r.reason)+'</td></tr>').join('')+'</tbody></table></div>':'<p class="calc-empty">Aucune activité ne correspond. Choisis un autre affichage ou change tes chiffres.</p>';
 const r=activityAnswerResult();
 $('inverse-results').innerHTML='<p class="calc-kicker">MA RÉPONSE</p><h3>'+esc(findActivity(state.inverse.selected)?.name||'Mon activité')+'</h3>'+(r.valid?'<p class="b-answer calc-answer">Avec '+nf.format(state.inverse.minutes)+' minutes, tu peux terminer '+r.runs+' activité(s) et gagner '+money(r.profit)+'.</p>'+stats([['Nombre de missions',nf.format(r.runs)],['Gagné en tout, achats de départ enlevés',money(r.profit)],['Tu auras à la fin',money(r.finalCapital)]]):warning(r.reason))+'<p class="calc-note">Une activité pas finie ne rapporte rien. Ce que tu achètes une seule fois n’est compté qu’une fois.</p>';
 syncActivityContext();
}
function activityAnswerResult(){return B.evaluate('activities',state,sourceActivities);}
function syncActivityContext(){
 document.querySelectorAll('[data-field^="goal."]').forEach(el=>{const key=el.dataset.field.slice(5);if(['capital','reserve','players'].includes(key)&&el!==document.activeElement){const cur=parseNumber(el.value);if(cur!==state.goal[key]&&!(state.goal[key]===null&&el.value.trim()===''))el.value=state.goal[key]??'';el.setAttribute('aria-invalid',String(!validField(el,state.goal[key])));}});
 const solo=state.goal.players===1&&document.activeElement?.id!=='activity-players';$('activity-group-size').hidden=solo;
 document.querySelectorAll('[name="activity-play-mode"]').forEach(el=>el.checked=el.value===(solo?'solo':'group'));
}
function validField(el,value){return value!==null&&Number.isFinite(value)&&value>=Number(el.dataset.min)&&value<=Number(el.dataset.max)&&(!el.dataset.integer||Number.isInteger(value));}
function activityAnnouncement(){const r=activityAnswerResult();return r.valid?nf.format(r.runs)+' activité(s) terminée(s), '+money(r.profit)+' de gain après mise initiale. Capital final : '+money(r.finalCapital)+'.':r.reason;}
function showActivityAnswer(){
 renderActivities();clearTimeout(liveTimer);clearTimeout(answerTimer);
 const answer=$('inverse-results');answer.classList.remove('is-highlighted');void answer.offsetWidth;answer.classList.add('is-highlighted');
 answerTimer=setTimeout(()=>answer.classList.remove('is-highlighted'),4000);
 const rect=answer.getBoundingClientRect(),top=(document.querySelector('header')?.getBoundingClientRect().bottom||0)+16;
 if(rect.top<top||rect.bottom>innerHeight-16)answer.scrollIntoView({block:rect.height>innerHeight-top-16?'start':'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
 $('activity-live').textContent='';requestAnimationFrame(()=>{$('activity-live').textContent='Réponse actualisée. '+activityAnnouncement();});
}
function loadActivityExample(id){
 const preset=D.presets.find(a=>a.id===id),index=state.activities.findIndex(a=>a.id===id);if(!preset||index<0)return;
 state.activities[index]=clone(initial.activities[index]);state.goal={...clone(initial.goal),capital:preset.example.capital,selected:id};state.inverse={selected:id,minutes:preset.example.minutes};state.model='cycles';
 document.querySelectorAll('[data-field]').forEach(el=>{const path=el.dataset.field;if(path==='model'||path.startsWith('goal.')||path.startsWith('inverse.')||path.startsWith('activities.'+index+'.')){let value=state;for(const part of path.split('.'))value=value[part];el.value=value??'';el.removeAttribute('aria-invalid');}});
 document.querySelector('[data-owned="'+index+'"]').checked=false;
 document.querySelectorAll('.calc-activity-editor>summary').forEach((el,i)=>el.textContent='Hypothèse '+String.fromCharCode(65+i)+' · '+state.activities[i].name);
 changed();showActivityAnswer();
}

function sessionResult(){return B.session(state,sourceActivities);}
function renderSession(){workspace.sessionRender();}
function selectItem(item,render=true){let a;try{a=B.addAsset(state,item);}catch(e){notify(e.message);return false;}state.purchase.key=a.key;state.tab='purchase';if(render){mount();saveLocal();$('f-purchase-price').focus();emit('catalogue_open');}return true;}
function renderPurchase(){const p=B.purchase(state,sourceActivities),item=catalogue.find(x=>x.id===p.itemId),meta=item?.fieldMeta?.price;
 $('purchase-selection').innerHTML=item?'<div class="calc-provenance"><strong>'+esc(item.name)+'</strong><p>'+(item.price===null?'Prix pas encore connu : écris celui que tu imagines.':'Prix de référence : '+money(item.price)+' · '+esc(statusLabels[meta?.status]||'Non confirmé'))+'</p><a href="'+esc(item.url)+'">Retour à la fiche ↗</a><p class="calc-note">'+esc(meta?.source?'Source : '+meta.source:'Aucune source de prix disponible.')+(meta?.verifiedAt?' · vérification : '+esc(meta.verifiedAt):'')+'</p><button class="calc-text-button" id="purchase-manual">Achat libre</button></div>':(p.itemId?warning('Cette fiche n’existe plus. Ton prix est gardé comme ton chiffre à toi.'):'<span class="calc-tag">MON PRIX À MOI</span>');
 const validExtras=Number.isFinite(p.extras)&&p.extras>=0,validReserve=Number.isFinite(p.capital)&&Number.isFinite(p.reserve)&&p.reserve>=0&&p.reserve<=p.capital;
 const q={...p,capital:p.capital-p.reserve,price:p.price===null||!validExtras?null:p.price+p.extras},r=validReserve?E.purchase(q):{valid:false,reason:'L’argent mis de côté doit être entre 0 et ce que tu as.'},c=E.compareBuy(q);
 let html='<p class="calc-kicker">MA RÉPONSE</p>';
 if(!r.valid)html+=warning(r.reason);else{html+='<p class="b-answer calc-answer">'+(r.shortfall?'Pas encore : il te manque '+money(r.shortfall)+'.':'Oui, tu peux l’acheter maintenant.')+'</p>'+stats([['Prix total',money(q.price)],['Il te restera',money(r.remaining+p.reserve)],['Sans l’argent mis de côté',money(r.remaining)]])+stats([['Temps de jeu pour regagner ce prix',hours(r.recoveryHours)],['Mon objectif si je n’achète pas',hours(c.saveHours)],['Mon objectif si j’achète',c.affordable?hours(c.buyHours):'Il faut d’abord l’argent']])+'<p class="calc-note">'+(p.boostHourly>0?'Après l’achat, tu gagnerais '+money(p.hourly+p.boostHourly)+' par heure de jeu.':'Achat pour le plaisir : il ne rapporte rien. Le temps affiché, c’est le temps de jeu pour regagner la même somme.')+'</p><details><summary>Comment est-ce calculé ?</summary><p class="calc-note">Argent utilisable = ce que tu as − ce que tu gardes de côté. Prix total = prix + options et frais. Temps pour l’objectif après l’achat = ce qu’il te manque ensuite ÷ ce que tu gagnes par heure. On suppose que tu gagnes toujours pareil. '+(item&&p.price!==item.price?'Ton prix personnel remplace la référence pour cette simulation seulement.':'')+'</p></details>';}
 if(r.valid&&!c.valid)html+=warning('On n’a pas encore ce que cet achat te rapporte. Le budget marche quand même ; remplis « Ça vaut le coup ? » pour comparer les temps.');
 $('purchase-results').innerHTML=html;
}
const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function near(a,b){if(Math.abs(a.length-b.length)>1)return false;let i=0,j=0,n=0;while(i<a.length&&j<b.length){if(a[i]===b[j]){i++;j++;continue;}if(++n>1)return false;if(a.length>=b.length)i++;if(b.length>=a.length)j++;}return n+(i<a.length||j<b.length?1:0)<=1;}
function searchMatch(item,q){let hay=normalize((item.brand||'')+' '+item.name+' '+item.category+' '+(labels[item.type]||'')+' '+(item.aliases||''));const aliases={voiture:'vehicule',bagnole:'vehicule',flingue:'equipement',arme:'equipement',maison:'demeure',mission:'activite'};return normalize(q).split(/\s+/).filter(Boolean).every(t=>{t=aliases[t]||t;return hay.includes(t)||(t.length>=5&&hay.split(/[^a-z0-9]+/).some(w=>near(t,w)));});}
function renderCatalogue(){const f=state.catalogue;let items=[...catalogue,...activityList().map(a=>({...a,type:'activity',category:'activité',image:null,price:null}))].filter(x=>(f.type==='all'||x.type===f.type)&&searchMatch(x,f.query)&&(!f.favoritesOnly||f.favorites.includes(x.id)));
 items=items.filter(x=>{const s=x.type==='activity'?x.status:x.fieldMeta?.price?.status||'unknown';return(f.status==='all'||f.status==='known'&&x.price!==null||f.status==='unknown'&&x.price===null&&x.type!=='activity'||s===f.status)&&(f.maxPrice===null||x.price!==null&&x.price<=f.maxPrice);});
 items.sort((a,b)=>f.sort==='name'?((a.brand||'')+' '+a.name).localeCompare((b.brand||'')+' '+b.name,'fr'):(a.price===null&&b.price===null?0:a.price===null?1:b.price===null?-1:(f.sort==='price-up'?a.price-b.price:b.price-a.price))||a.name.localeCompare(b.name,'fr'));
 $('catalogue-count').textContent=items.length+' résultat'+(items.length>1?'s':'')+(f.maxPrice!==null?' · prix inconnus exclus':'');
 const chips=[['query',f.query],['type',f.type!=='all'?labels[f.type]:null],['status',f.status!=='all'?$('catalogue-status').selectedOptions[0]?.textContent:null],['maxPrice',f.maxPrice!==null?'≤ '+money(f.maxPrice):null],['favoritesOnly',f.favoritesOnly?'Favoris':null]].filter(x=>x[1]);
 $('catalogue-filter-chips').innerHTML=chips.map(([k,v])=>'<button class="calc-chip" data-remove-filter="'+k+'">'+esc(v)+' ×</button>').join('')+(chips.length?'<button class="calc-text-button" data-reset-filters="1">Tout réinitialiser</button>':'');
 $('catalogue-results').innerHTML=items.slice(0,catalogueLimit).map(x=>({...x,image:x.image||x.schemaImage})).map(x=>'<article class="calc-product" data-product="'+esc(x.id)+'"><div class="calc-product-media">'+(x.image?'<img src="'+esc(x.image)+'" data-image-fallback="'+esc(x.imageFallback||'')+'" class="'+(/(\.svg$|^data:image\/svg)/i.test(x.image)?'is-schema':'')+'" alt="" width="480" height="270" loading="lazy" decoding="async">':'')+'<div class="calc-product-placeholder" '+(x.image?'hidden':'')+' aria-hidden="true"><span>'+esc(labels[x.type]||'Mon plan')+'</span><small>'+esc(x.category||'Visuel indisponible')+'</small></div></div><div><span class="calc-tag">'+esc(labels[x.type]||x.type)+'</span><h4>'+esc((x.brand?x.brand+' ':'')+x.name)+'</h4><p>'+(x.type==='activity'?'Activité · '+esc(statusLabels[x.status]||'Non confirmé'):x.price===null?'Prix pas encore connu':money(x.price)+' · '+esc(statusLabels[x.fieldMeta?.price?.status]||'Non confirmé'))+'</p>'+(x.type==='activity'?'<button class="calc-button" data-activity="'+esc(x.id)+'">Calculer mon objectif</button>':'<button class="calc-button" data-item="'+esc(x.id)+'">Je veux celui-là</button> <button class="calc-button" data-b-roi="'+esc(x.id)+'">Calculer si ça vaut le coup</button> <a href="'+esc(x.url)+'">Fiche ↗</a>')+'<button class="calc-text-button" data-favorite="'+esc(x.id)+'" aria-pressed="'+f.favorites.includes(x.id)+'">'+(f.favorites.includes(x.id)?'★ Retirer des favoris':'☆ Mettre en favori')+'</button>'+(x.type!=='activity'?'<label class="calc-check calc-compare-option"><input type="checkbox" data-compare="'+esc(x.id)+'" '+(f.compareIds.includes(x.id)?'checked':'')+'> '+(f.compareIds.includes(x.id)?'✓ Dans ma comparaison':'Comparer')+'</label>':'')+'</div></article>').join('')||'<div class="calc-empty"><h4>On n’a rien trouvé.</h4><p>Essaie un autre mot, enlève le prix maximum ou choisis « Toutes les catégories ».</p><button class="calc-button" data-reset-filters="1">Retirer tous les filtres</button></div>';
 $('catalogue-more').hidden=items.length<=catalogueLimit;renderComparison();
}
function comparisonItems(){return state.catalogue.compareIds.map(id=>catalogue.find(x=>x.id===id)).filter(Boolean);}
function comparisonTable(items,rows,caption){
 const value=(x,k)=>{
  if(x[k]===null||x[k]===undefined)return '<span class="calc-unknown">Pas encore connu</span>';
  if(k==='type')return esc(labels[x.type]||x.type);
  if(k==='category')return esc(x.category||'');
  const meta=x.fieldMeta?.[k]||{},unit=meta.unit||(k==='price'?'$':k==='seats'?'places':'');
  return esc(k==='price'?money(x[k]):nf.format(x[k])+(unit?' '+unit:''))+'<br><small>'+esc(statusLabels[meta.status]||'Non confirmé')+'</small>';
 };
 return '<div class="calc-table-wrap" tabindex="0" role="region" aria-label="'+esc(caption)+'"><table class="calc-table"><caption>'+esc(caption)+'</caption><thead><tr><th scope="col">Critère</th>'+items.map(x=>'<th scope="col">'+esc((x.brand?x.brand+' ':'')+x.name)+' <button type="button" class="calc-text-button" data-remove-compare="'+esc(x.id)+'" aria-label="Retirer '+esc(x.name)+' de la comparaison">×</button></th>').join('')+'</tr></thead><tbody>'+rows.map(([l,k])=>'<tr><th scope="row">'+esc(l)+'</th>'+items.map(x=>'<td>'+value(x,k)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
}
function renderComparison(){
 const items=comparisonItems();state.catalogue.compareIds=items.map(x=>x.id);const box=$('vehicle-comparison');
 document.querySelectorAll('[data-compare]').forEach(el=>{const on=state.catalogue.compareIds.includes(el.dataset.compare);el.checked=on;el.closest('.calc-product')?.classList.toggle('is-selected',on);const t=el.nextSibling;if(t&&t.nodeType===3)t.textContent=on?' ✓ Dans ma comparaison':' Comparer';});
 if(!items.length){box.innerHTML='<p class="calc-empty">Coche « Comparer » sur 2 ou 3 fiches pour les voir côte à côte.</p>';box.classList.remove('is-active');return;}
 box.classList.add('is-active');
 const head='<div class="calc-compare-bar"><p class="calc-kicker">MA COMPARAISON</p><p class="calc-compare-count" role="status">'+items.length+' fiche'+(items.length>1?'s':'')+' sur 3'+(items.length<2?' : coche encore une fiche pour comparer.':'')+'</p><div class="calc-compare-chips">'+items.map(x=>'<button type="button" class="calc-chip" data-remove-compare="'+esc(x.id)+'" aria-label="Retirer '+esc(x.name)+' de la comparaison">'+esc(x.name)+' ×</button>').join('')+'</div></div>';
 const vehicles=items.filter(x=>x.type==='vehicle');
 box.innerHTML=head+comparisonTable(items,[['Type','type'],['Catégorie','category'],['Prix','price']],(items.length>1?'Ce qu’on sait sur ces '+items.length+' fiches':'Ce qu’on sait sur cette fiche'))+(vehicles.length?'<h4>Pour les véhicules</h4>'+comparisonTable(vehicles,[['Vitesse','speed'],['Accélération','acceleration'],['Places','seats']],'Véhicules seulement'):'')+'<p class="calc-note">Une valeur pas encore connue reste vide. On ne donne pas de note ni de classement tant qu’il manque des informations.</p>';
}
function refreshCatalogueFilters(){
 $('catalogue-search').value=state.catalogue.query;$('catalogue-type').value=state.catalogue.type;$('catalogue-status').value=state.catalogue.status;$('catalogue-budget').value=state.catalogue.maxPrice??'';$('catalogue-budget').removeAttribute('aria-invalid');$('catalogue-sort').value=state.catalogue.sort;$('catalogue-favorites').checked=state.catalogue.favoritesOnly;catalogueLimit=6;renderCatalogue();saveLocal();
}
