document.addEventListener('input',ev=>{if(workspace.event(ev))return;const el=ev.target;if(el.matches('input[data-field]')){const value=el.dataset.number?parseNumber(el.value):el.value;if(el.dataset.field==='session.minutes'&&state.session.usualMinutes===state.session.minutes)state.session.usualMinutes=value;setPath(el.dataset.field,value);if(el.dataset.number){const ok=validField(el,value);el.setAttribute('aria-invalid',String(!ok));const err=$(el.id+'-error');if(err){err.hidden=ok;err.textContent=ok?'':'Saisis '+(el.dataset.integer?'un entier':'un nombre')+' entre '+el.dataset.min+' et '+el.dataset.max+'.';}}changed();}if(el.id==='catalogue-search'){state.catalogue.query=el.value;catalogueLimit=6;renderCatalogue();saveLocal();}if(el.id==='catalogue-budget'){const val=el.value.trim()===''?null:parseNumber(el.value);el.setAttribute('aria-invalid',String(el.value.trim()!==''&&(val===null||val<0)));state.catalogue.maxPrice=val!==null&&val>=0&&val<=1e12?val:null;catalogueLimit=6;renderCatalogue();saveLocal();}if(el.id==='calc-name'){state.name=el.value.slice(0,100)||'Mon plan';saveLocal();}});
document.addEventListener('change',ev=>{if(workspace.event(ev))return;const el=ev.target;if(/-play-mode$/.test(el.name||'')){state.goal.players=el.value==='solo'?1:Math.max(2,state.goal.players||2);document.querySelectorAll('[data-field="goal.players"]').forEach(i=>{i.value=state.goal.players;});document.querySelectorAll('.calc-group-size,#activity-group-size').forEach(g=>{g.hidden=state.goal.players===1;});document.querySelectorAll('[name$="-play-mode"]').forEach(i=>{i.checked=i.value===(state.goal.players===1?'solo':'group');});changed();}if(el.matches('select[data-field]')){setPath(el.dataset.field,el.value);changed();}if(el.dataset.owned!==undefined){state.activities[Number(el.dataset.owned)].owned=el.checked;changed();}if(el.dataset.sessionActivity){const id=el.dataset.sessionActivity;state.session.enabled=el.checked?[...new Set([...state.session.enabled,id])]:state.session.enabled.filter(x=>x!==id);changed();}if(el.id==='activity-filter')renderActivities();const filters={'catalogue-type':'type','catalogue-status':'status','catalogue-sort':'sort'};if(filters[el.id]){state.catalogue[filters[el.id]]=el.value;catalogueLimit=6;renderCatalogue();saveLocal();}if(el.id==='catalogue-favorites'){state.catalogue.favoritesOnly=el.checked;renderCatalogue();saveLocal();}if(el.dataset.compare){const id=el.dataset.compare;if(el.checked&&state.catalogue.compareIds.length>=3){el.checked=false;notify('Compare jusqu’à trois fiches à la fois.');return;}state.catalogue.compareIds=el.checked?[...state.catalogue.compareIds,id]:state.catalogue.compareIds.filter(x=>x!==id);renderComparison();saveLocal();emit('compare');if(el.checked&&state.catalogue.compareIds.length>=2){const box=$('vehicle-comparison');box.classList.remove('is-highlighted');void box.offsetWidth;box.classList.add('is-highlighted');const r=box.getBoundingClientRect();if(r.top>innerHeight-120)box.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}}});
document.addEventListener('click',ev=>{if(workspace.event(ev))return;const b=ev.target.closest('button');if(!b)return;const d=b.dataset;
 if(b.id==='activity-answer')showActivityAnswer();
 if(d.activityExample)loadActivityExample(d.activityExample);
 if(d.guideFocus){$(d.guideFocus)?.focus();$(d.guideFocus)?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}if(d.tab)switchTab(d.tab);if(d.open)openTab(d.open);
 if(d.bMode&&!d.mode)d.mode=d.bMode;
 if(d.mode&&['quick','guided','advanced'].includes(d.mode)){state.mode=d.mode;state.views[state.tab]=d.mode;modeUI();workspace.render();saveLocal();}
 if(d.target){state.goal.target=Number(d.target);$('f-goal-target').value=d.target;changed();}
 if(d.daily){state.goal.dailyMinutes=Number(d.daily);$('f-goal-dailyMinutes').value=d.daily;changed();}
 if(d.inverseMinutes){state.inverse.minutes=Number(d.inverseMinutes);$('f-inverse-minutes').value=d.inverseMinutes;changed();}
 if(d.sessionMinutes){if(state.session.usualMinutes===state.session.minutes)state.session.usualMinutes=Number(d.sessionMinutes);state.session.minutes=Number(d.sessionMinutes);$('f-session-minutes').value=d.sessionMinutes;changed();}
 if(d.scenario||d.activity){state.model='cycles';state.goal.selected=d.scenario||d.activity;$('f-model').value='cycles';$('f-goal-selected').value=state.goal.selected;changed();if(d.activity)openTab('goal');}
 if(d.item){const item=catalogue.find(x=>x.id===d.item);if(item)selectItem(item);}
 if(b.id==='purchase-manual'){let a=state.assets.find(a=>!a.itemId);if(!a){if(state.assets.length>=40){notify('40 achats maximum. Télécharge ton calcul avant d’en retirer.');return;}a={key:'free-'+Date.now().toString(36),itemId:'',name:'Mon achat libre',price:null,referencePrice:null,extras:0,fees:0,owned:false,incomeMode:'none',boostHourly:0};state.assets.push(a);}state.purchase.key=a.key;mount();saveLocal();$('f-purchase-price').focus();}
 if(b.id==='catalogue-more'){catalogueLimit+=12;renderCatalogue();}
 if(d.favorite){state.catalogue.favorites=state.catalogue.favorites.includes(d.favorite)?state.catalogue.favorites.filter(x=>x!==d.favorite):[...state.catalogue.favorites,d.favorite].slice(-100);renderCatalogue();saveLocal();}
 if(d.removeCompare){state.catalogue.compareIds=state.catalogue.compareIds.filter(x=>x!==d.removeCompare);renderComparison();saveLocal();}
 if(d.removeFilter){state.catalogue[d.removeFilter]=initial.catalogue[d.removeFilter];refreshCatalogueFilters();$('catalogue-search').focus({preventScroll:true});}
 if(d.resetFilters)resetFilters();

});
